 "content": "from collections import Counter, defaultdict


def transform(grid):
    h, w = len(grid), len(grid[0])
    best = None
    # The patterned field begins inside the colored frame. Fit a cyclic
    # diagonal sequence to observed nonzero cells and choose the shortest
    # period achieving the strongest agreement.
    for period in range(2, 11):
        buckets = defaultdict(Counter)
        for r in range(3, h):
            for c in range(3, w):
                value = grid[r][c]
                if value:
                    buckets[(r + c) % period][value] += 1
        mapping = {k: counts.most_common(1)[0][0] for k, counts in buckets.items()}
        score = sum(counts[mapping[k]] for k, counts in buckets.items())
        total = sum(sum(counts.values()) for counts in buckets.values())
        candidate = (score / total if total else 0, score, -period, period, mapping)
        if best is None or candidate[:3] > best[:3]:
            best = candidate
    _, _, _, period, mapping = best
    out = [row[:] for row in grid]
    # Missing cells in the patterned field are reconstructed from the fitted
    # diagonal cycle; keep the frame and every observed cell unchanged.
    for r in range(3, h):
        for c in range(3, w):
            if out[r][c] == 0:
                out[r][c] = mapping[(r + c) % period]
    return out


if __name__ == '__main__':
